// Exact rational arithmetic on BigInt. Share counts must never touch floating point.

function gcd(a, b) {
  a = a < 0n ? -a : a;
  b = b < 0n ? -b : b;
  while (b) [a, b] = [b, a % b];
  return a;
}

export function frac(n, d = 1) {
  let num = BigInt(n);
  let den = BigInt(d);
  if (den === 0n) throw new Error('zero denominator');
  if (den < 0n) { num = -num; den = -den; }
  const g = gcd(num, den) || 1n;
  return { n: num / g, d: den / g };
}

export const mul = (a, b) => frac(a.n * b.n, a.d * b.d);
export const floorInt = (a) => a.n / a.d;
export const remainder = (a) => frac(a.n % a.d, a.d);
export const isZero = (a) => a.n === 0n;
export const toNumber = (a) => Number(a.n) / Number(a.d);
export const toString = (a) => (a.d === 1n ? `${a.n}` : `${a.n}/${a.d}`);

// Person-name matching for Indian financial records: initials ("R. G."), surname-first
// order ("Wankhede R G"), honorifics and small spelling drift. Scores are heuristic,
// so every non-exact match is shown to the heir for confirmation.

const HONORIFICS = new Set(['SHRI', 'SHREE', 'SRI', 'SMT', 'KUM', 'KUMARI', 'MR', 'MRS', 'MS', 'DR', 'LATE']);

export function personTokens(name) {
  return String(name || '')
    .toUpperCase()
    .replace(/[.,]/g, ' ')
    .replace(/[^A-Z\s]/g, '')
    .split(/\s+/)
    .filter((t) => t && !HONORIFICS.has(t));
}

function levenshtein(a, b) {
  const dp = Array.from({ length: b.length + 1 }, (_, j) => j);
  for (let i = 1; i <= a.length; i++) {
    let prev = dp[0];
    dp[0] = i;
    for (let j = 1; j <= b.length; j++) {
      const tmp = dp[j];
      dp[j] = Math.min(dp[j] + 1, dp[j - 1] + 1, prev + (a[i - 1] === b[j - 1] ? 0 : 1));
      prev = tmp;
    }
  }
  return dp[b.length];
}

export function similarity(a, b) {
  if (!a.length && !b.length) return 1;
  return 1 - levenshtein(a, b) / Math.max(a.length, b.length);
}

function alignGiven(docGiven, refGiven) {
  let j = 0;
  let initials = 0;
  let skipped = 0;
  for (const t of docGiven) {
    while (j < refGiven.length) {
      const r = refGiven[j];
      if (t === r) { j++; break; }
      if (t.length === 1 && r[0] === t) { initials++; j++; break; }
      skipped++;
      j++;
    }
    if (j > refGiven.length) return null;
    if (j === refGiven.length && !(t === refGiven[j - 1] || (t.length === 1 && refGiven[j - 1]?.[0] === t))) return null;
  }
  return { initials, skipped: skipped + (refGiven.length - j) };
}

export function matchPerson(docName, refName) {
  const doc = personTokens(docName);
  const ref = personTokens(refName);
  if (!doc.length || !ref.length) return { score: 0, kind: 'unreadable', needsAffidavit: false };
  if (doc.join(' ') === ref.join(' ')) return { score: 1, kind: 'exact', needsAffidavit: false };

  const orientations = [{ tokens: doc, rotated: false }];
  if (doc.length > 1) orientations.push({ tokens: [...doc.slice(1), doc[0]], rotated: true });

  let best = { score: 0, kind: 'no_match', needsAffidavit: false };
  const refSurname = ref[ref.length - 1];
  for (const { tokens, rotated } of orientations) {
    const surname = tokens[tokens.length - 1];
    const surnameSim = similarity(surname, refSurname);
    if (surnameSim < 0.8) continue;
    const aligned = alignGiven(tokens.slice(0, -1), ref.slice(0, -1));
    if (!aligned) continue;
    let score = 0.97;
    if (aligned.initials) score -= 0.05;
    score -= 0.08 * aligned.skipped;
    if (rotated) score -= 0.03;
    if (surnameSim < 1) score -= 0.15;
    const kind = surnameSim < 1 ? 'spelling' : aligned.initials ? 'initials' : aligned.skipped ? 'partial' : rotated ? 'reordered' : 'exact';
    if (score > best.score) best = { score: Math.round(score * 100) / 100, kind, needsAffidavit: true };
  }
  return best;
}

