// Walks the document's given names left to right against the reference's given names.
// A reference name may be skipped (missing middle name); a document name may not.
function alignGiven(docGiven, refGiven) {
  let j = 0;
  let initials = 0;
  let skipped = 0;
  for (const t of docGiven) {
    let matched = false;
    while (j < refGiven.length) {
      const r = refGiven[j++];
      if (t === r) { matched = true; break; }
      if (t.length === 1 && r[0] === t) { initials++; matched = true; break; }
      skipped++;
    }
    if (!matched) return null;
  }
  return { initials, skipped: skipped + (refGiven.length - j) };
}

