// Resolves the company name written on an old document to a company in the lineage graph.
// Returns ranked candidates and a decision: 'auto' (use it), 'ask' (heir must confirm),
// or 'unknown' (do not guess).

const ABBREVIATIONS = {
  CO: 'COMPANY', COY: 'COMPANY', CORPN: 'CORPORATION', CORP: 'CORPORATION', LTD: 'LIMITED',
  PVT: 'PRIVATE', MFG: 'MANUFACTURING', INDS: 'INDUSTRIES', INTL: 'INTERNATIONAL', DEVT: 'DEVELOPMENT',
};
const STOPWORDS = new Set(['THE', 'LIMITED', 'AND', 'OF', 'PRIVATE']);

export const AUTO_THRESHOLD = 0.85;
export const ASK_THRESHOLD = 0.6;
const AUTO_MARGIN = 0.1;

export function companyTokens(name) {
  return String(name || '')
    .toUpperCase()
    .replace(/&/g, ' AND ')
    .replace(/[^A-Z0-9\s]/g, ' ')
    .split(/\s+/)
    .filter(Boolean)
    .map((t) => ABBREVIATIONS[t] || t)
    .filter((t) => !STOPWORDS.has(t));
}

function bigrams(s) {
  const out = new Map();
  for (let i = 0; i < s.length - 1; i++) {
    const g = s.slice(i, i + 2);
    out.set(g, (out.get(g) || 0) + 1);
  }
  return out;
}

function dice(a, b) {
  if (a.length < 2 || b.length < 2) return a === b ? 1 : 0;
  const A = bigrams(a);
  const B = bigrams(b);
  let overlap = 0;
  for (const [g, c] of A) overlap += Math.min(c, B.get(g) || 0);
  return (2 * overlap) / (a.length - 1 + (b.length - 1));
}

function jaccard(a, b) {
  const A = new Set(a);
  const B = new Set(b);
  const inter = [...A].filter((t) => B.has(t)).length;
  const union = new Set([...A, ...B]).size;
  return union ? inter / union : 0;
}

export function scoreCompanyName(docName, candidateName) {
  const a = companyTokens(docName);
  const b = companyTokens(candidateName);
  if (!a.length || !b.length) return 0;
  const tokenScore = jaccard(a, b);
  const charScore = dice(a.join(''), b.join(''));
  let score = Math.max(tokenScore, 0.95 * charScore);
  // A lone short token may be an acronym ("HLL"). Acronyms are ambiguous, so cap below auto.
  if (a.length === 1 && a[0].length >= 2 && a[0].length <= 6 && b.length > 1) {
    const initials = b.map((t) => t[0]).join('');
    if (initials === a[0]) score = Math.max(score, 0.75);
  }
  return Math.round(score * 100) / 100;
}

export function resolveCompany(graph, docName) {
  const scored = [];
  for (const c of graph.companies) {
    const names = [...c.names.map((n) => n.name), ...(c.aliases || [])];
    let best = { score: 0, matchedName: null };
    for (const n of names) {
      const s = scoreCompanyName(docName, n);
      if (s > best.score) best = { score: s, matchedName: n };
    }
    scored.push({ companyId: c.id, ...best });
  }
  scored.sort((x, y) => y.score - x.score);
  const [top, second] = scored;
  const margin = top.score - (second?.score || 0);
  let decision = 'unknown';
  if (top.score >= AUTO_THRESHOLD && margin >= AUTO_MARGIN) decision = 'auto';
  else if (top.score >= ASK_THRESHOLD) decision = 'ask';
  return { decision, top, candidates: scored.slice(0, 3) };
}

// Looks up the version of a rule that was in force on a given date.

export function ruleAt(rulesData, id, asOf) {
  const versions = rulesData.rules.filter((r) => r.id === id);
  if (!versions.length) throw new Error(`unknown rule ${id}`);
  const rule = versions.find((r) => r.effective_from <= asOf && (!r.effective_to || asOf < r.effective_to));
  if (!rule) throw new Error(`no version of ${id} in force on ${asOf}`);
  return { ...rule, stale: Boolean(rule.review_by && rule.review_by < asOf) };
}

export function citation(rule) {
  return {
    ref: `${rule.id} v${rule.version}`,
    kind: rule.kind,
    summary: rule.summary,
    source: rule.source,
    effective_from: rule.effective_from,
    effective_to: rule.effective_to,
    stale: rule.stale,
  };
}

// Follows a holding through renames, splits, bonuses and mergers using only curated,
// cited events. Never invents an event: gaps in coverage lower the status instead.

import { frac, mul, floorInt, remainder, isZero, toString } from './fraction.js';

export const companyById = (graph, id) => graph.companies.find((c) => c.id === id);

export function nameOn(company, date) {
  const hit = company.names.find((n) => (!n.from || n.from <= date) && (!n.until || date < n.until));
  return (hit || company.names[company.names.length - 1]).name;
}

export const currentName = (company) => company.names[company.names.length - 1].name;

export function faceValueOn(company, date) {
  if (!company.face_values) return null;
  const hit = company.face_values.find((f) => !f.until || date < f.until);
  return hit ? hit.value : null;
}

function describe(event, before, after, graph) {
  if (event.type === 'rename') return `${event.label}: name is now "${event.new_name}"`;
  if (event.type === 'merger') {
    const into = currentName(companyById(graph, event.into));
    return `${event.label}. ${before} shares became ${after} shares of ${into} (as named today)`;
  }
  return `${event.label}: ${before} shares became ${after}`;
}

// heldSince: the date the holding is known to exist (certificate or statement date).
export function traceHolding(graph, { companyId, shares, heldSince }) {
  let company = companyById(graph, companyId);
  if (!company) return { status: 'unknown', path: [], warnings: ['Company not in lineage graph.'] };

  const path = [];
  const warnings = [];
  const fractions = [];
  let count = BigInt(shares);
  let status = 'confirmed';
  let since = heldSince;
  let inclusive = true;

  for (let hops = 0; hops < 20; hops++) {
    if (company.synthetic) warnings.push(`${currentName(company)} is a synthetic test company.`);
    if (since < company.verified_from) {
      status = 'likely';
      warnings.push(
        `Events for ${nameOn(company, since)} before ${company.verified_from} are not verified; ` +
          `the registrar may report more shares than shown.`,
      );
    }
    if (company.status === 'struck_off') {
      return {
        status: 'doubtful',
        finalCompanyId: company.id,
        finalName: currentName(company),
        shares: Number(count),
        fractions,
        path,
        warnings: [...warnings, `${currentName(company)} was struck off on ${company.struck_off_on}. Value is doubtful unless the company is restored.`],
      };
    }

    const events = graph.events
      .filter((e) => e.company === company.id && (inclusive ? e.record_date >= since : e.record_date > since))
      .sort((a, b) => a.record_date.localeCompare(b.record_date));

    let mergedInto = null;
    for (const e of events) {
      const before = count;
      if (e.type === 'split') {
        count = floorInt(mul(frac(count), frac(e.ratio[0], e.ratio[1])));
      } else if (e.type === 'bonus') {
        const exact = mul(frac(count), frac(e.ratio[1] + e.ratio[0], e.ratio[1]));
        count = floorInt(exact);
        if (!isZero(remainder(exact))) fractions.push({ event: e.id, fraction: toString(remainder(exact)) });
      } else if (e.type === 'merger') {
        const exact = mul(frac(count), frac(e.ratio[0], e.ratio[1]));
        count = floorInt(exact);
        if (!isZero(remainder(exact))) {
          fractions.push({ event: e.id, fraction: toString(remainder(exact)), of: e.into });
        }
      }
      path.push({
        event: e.id,
        type: e.type,
        date: e.record_date,
        sharesBefore: Number(before),
        sharesAfter: Number(count),
        text: describe(e, before, count, graph),
        source: e.source,
      });
      if (e.type === 'merger') { mergedInto = e; break; }
    }

    if (!mergedInto) {
      if (company.status === 'merged') {
        warnings.push(`${currentName(company)} is marked merged but no merger event applies after ${since}.`);
        status = 'likely';
      }
      return { status, finalCompanyId: company.id, finalName: currentName(company), shares: Number(count), fractions, path, warnings };
    }
    company = companyById(graph, mergedInto.into);
    since = mergedInto.record_date;
    inclusive = false;
  }
  throw new Error('lineage loop');
}

// Turns human-confirmed facts about a deceased person's assets into an ordered, cited claim plan.
// Input facts are assumed to have passed the heir's confirmation step; nothing here calls a model.

import { resolveCompany } from './companies.js';
import { matchPerson, personTokens } from './names.js';
import { traceHolding, companyById, currentName, faceValueOn, nameOn } from './lineage.js';
import { ruleAt, citation } from './rules.js';

const MS_PER_YEAR = 365.25 * 24 * 3600 * 1000;
const yearsBetween = (a, b) => (new Date(b) - new Date(a)) / MS_PER_YEAR;
const inr = (n) => `Rs ${Math.round(n).toLocaleString('en-IN')}`;

function nameVariants(panName, docNames) {
  const t = personTokens(panName);
  const out = new Set([panName]);
  if (t.length > 1) {
    const given = t.slice(0, -1);
    const surname = t[t.length - 1];
    out.add(`${given.map((g) => g[0]).join(' ')} ${surname}`);
    out.add(`${surname} ${given.join(' ')}`);
    out.add(`${surname} ${given.map((g) => g[0]).join(' ')}`);
  }
  for (const d of docNames) if (d) out.add(d);
  return [...out];
}

export function buildPlan(input, kb) {
  const asOf = input.as_of;
  const citations = new Map();
  const flags = [];
  const docNeeds = new Map();

  const cite = (id) => {
    const r = ruleAt(kb.rules, id, asOf);
    const ref = `${r.id} v${r.version}`;
    citations.set(ref, citation(r));
    if (r.stale) addFlag('STALE_RULE', 'warn', `Rule ${ref} is past its review date (${r.review_by}).`, [ref]);
    return ref;
  };
  const ruleInForce = (id) => {
    try { return ruleAt(kb.rules, id, asOf); } catch { return null; }
  };
  function addFlag(code, severity, message, refs = [], asset = null) {
    flags.push({ code, severity, message, refs, asset });
  }
  const need = (docId, assetLabel, refs = []) => {
    const meta = kb.documents.documents[docId];
    if (!meta) throw new Error(`unknown document ${docId}`);
    const entry = docNeeds.get(docId) || { id: docId, ...meta, forAssets: new Set(), refs: new Set() };
    entry.forAssets.add(assetLabel);
    refs.forEach((r) => entry.refs.add(r));
    docNeeds.set(docId, entry);
  };

  const deceased = input.deceased;
  const allDocNames = input.assets.map((a) => a.holder_name_on_doc);

  // Pass 1: resolve, trace and value every share holding, so thresholds can be grouped.
  const prepared = input.assets.map((a, index) => {
    const label = a.kind === 'shares' ? `Shares: ${a.company_name_on_doc}` : `${a.type === 'fd' ? 'Fixed deposit' : 'Savings account'}: ${a.bank}`;
    const holderMatch = matchPerson(a.holder_name_on_doc, deceased.pan_name);
    if (a.kind !== 'shares') return { a, index, label, holderMatch };
    const resolution = resolveCompany(kb.graph, a.company_name_on_doc);
    if (resolution.decision === 'unknown') return { a, index, label, holderMatch, resolution };
    const trace = traceHolding(kb.graph, { companyId: resolution.top.companyId, shares: a.shares, heldSince: a.held_since });
    const price = kb.prices.prices[trace.finalCompanyId];
    const value = price && trace.status !== 'doubtful'
      ? { low: trace.shares * price * (1 - kb.prices.band), high: trace.shares * price * (1 + kb.prices.band), basis: `illustrative price ${inr(price)}` }
      : null;
    return { a, index, label, holderMatch, resolution, trace, value };
  });

  const groupKey = (p) => (p.a.mode === 'demat' ? `demat:${p.a.dp_account || p.index}` : `physical:${p.trace?.finalCompanyId}`);
  const groupValue = new Map();
  for (const p of prepared) {
    if (!p.value) continue;
    const g = groupValue.get(groupKey(p)) || { low: 0, high: 0 };
    g.low += p.value.low;
    g.high += p.value.high;
    groupValue.set(groupKey(p), g);
  }

  const assets = prepared.map((p) => (p.a.kind === 'shares' ? planShares(p) : planDeposit(p)));

  function checkHolder(p) {
    const m = p.holderMatch;
    if (m.score < 0.6) {
      addFlag('NAME_UNMATCHED', 'block', `"${p.a.holder_name_on_doc}" does not match the deceased's PAN name "${deceased.pan_name}". The heir must confirm this asset belongs to the deceased before anything else.`, [], p.label);
    } else if (m.needsAffidavit) {
      const ref = cite('NAME_VARIANCE');
      addFlag('NAME_VARIANT', 'warn', `Name on document "${p.a.holder_name_on_doc}" differs from PAN name "${deceased.pan_name}" (${m.kind}, score ${m.score}). Prepare a name-variance affidavit in the same notary visit.`, [ref], p.label);
      need('name_variance_affidavit', p.label, [ref]);
    }
  }

  function planShares(p) {
    const { a, label, resolution } = p;
    const steps = [];
    checkHolder(p);

    if (resolution.decision === 'unknown') {
      addFlag('COMPANY_UNKNOWN', 'block', `"${a.company_name_on_doc}" could not be matched to any company in the lineage graph (best guess "${resolution.top.matchedName}", score ${resolution.top.score}). Virasat does not guess.`, [], label);
      steps.push({ key: 'identify_company', who: 'heir', text: `Identify the company: search MCA company master data and stock-exchange announcements for "${a.company_name_on_doc}", and look for any letter or dividend warrant from the company.` });
      return { label, kind: 'shares', status: 'unknown', holderMatch: p.holderMatch, resolution, steps };
    }

    let { trace } = p;
    let status = trace.status;
    const startCompany = companyById(kb.graph, resolution.top.companyId);
    if (resolution.decision === 'ask') {
      addFlag('COMPANY_CONFIRM', 'warn', `"${a.company_name_on_doc}" probably means "${resolution.top.matchedName}" (score ${resolution.top.score}). The heir must confirm before this lead is trusted.`, [], label);
      steps.push({ key: 'confirm_company', who: 'heir', text: `Confirm that "${a.company_name_on_doc}" is "${resolution.top.matchedName}".` });
      if (status === 'confirmed') status = 'likely';
    }
    trace.warnings.forEach((w) => addFlag('LINEAGE_NOTE', 'info', w, [], label));

    if (a.face_value != null) {
      const fv = faceValueOn(startCompany, a.held_since);
      if (fv != null && fv !== a.face_value) {
        addFlag('FACE_VALUE_MISMATCH', 'warn', `Document shows face value Rs ${a.face_value}, but ${nameOn(startCompany, a.held_since)} shares had face value Rs ${fv} on ${a.held_since}. Check the document date before trusting the share count.`, [], label);
        if (status === 'confirmed') status = 'likely';
      }
    }

    if (status === 'doubtful') {
      const ref = cite('STRUCK_OFF_RESTORATION');
      addFlag('STRUCK_OFF', 'block', `${trace.finalName} is struck off. No claim form applies; restoration is a legal process.`, [ref], label);
      steps.push({ key: 'advocate_restoration', who: 'advocate', text: `Consult an advocate on whether restoring ${trace.finalName} through the NCLT is worth it for this holding.`, refs: [ref] });
      return { label, kind: 'shares', status, holderMatch: p.holderMatch, resolution, trace, steps };
    }

    const finalName = trace.finalName;
    const limitRule = ruleAt(kb.rules, 'SEBI_TRANSMISSION_LIMIT', asOf);
    const limitRef = cite('SEBI_TRANSMISSION_LIMIT');
    const limit = a.mode === 'demat' ? limitRule.params.demat_limit : limitRule.params.physical_limit;
    const gv = groupValue.get(groupKey(p));
    let band = 'unknown';
    if (gv) band = gv.high <= limit ? 'within' : gv.low > limit ? 'above' : 'boundary';
    const threshold = { limit, band, rule: limitRef, groupLow: gv?.low, groupHigh: gv?.high };

    if (trace.fractions.length) {
      const f = trace.fractions.map((x) => x.fraction).join(', ');
      addFlag('FRACTION', 'info', `Fractional entitlement (${f} share) is not issued as a share; schemes usually sell fractions and pay cash. If that cheque was never encashed, ask the registrar.`, [], label);
    }

    // Documents
    need('death_certificate', label);
    need('claimant_kyc', label);
    if (a.mode === 'physical') {
      if (a.original_available === false) {
        need('duplicate_certificate', label, [cite('IEPF_INDEMNITY_STAMP')]);
        addFlag('MISSING_ORIGINAL', 'warn', 'Original certificate is missing. A duplicate must be obtained from the registrar before transmission.', [], label);
      } else {
        need('original_certificate', label);
      }
      need('isr5_form', label, [limitRef]);
    } else {
      need('dp_transmission_form', label, [limitRef]);
    }
    need('demat_account', label);

    if (!a.nominee) {
      need('affidavit_heirs', label, [limitRef]);
      if (band === 'within') {
        need('indemnity_bond', label, [limitRef]);
        need('noc_heirs', label, [limitRef]);
      } else if (band === 'above') {
        if (limitRule.params.legal_heir_cert_accepted) {
          need('legal_heir_certificate', label, [limitRef, cite('HEIR_CERT_STATE')]);
          need('indemnity_bond', label, [limitRef]);
          need('noc_heirs', label, [limitRef]);
          addFlag('ABOVE_LIMIT', 'info', `Estimated value ${inr(gv.low)}-${inr(gv.high)} is above the ${inr(limit)} limit: a legal heirship certificate (or succession certificate) is required.`, [limitRef], label);
        } else {
          need('succession_certificate', label, [limitRef]);
          addFlag('ABOVE_LIMIT', 'warn', `Estimated value ${inr(gv.low)}-${inr(gv.high)} is above the ${inr(limit)} limit in force on ${asOf}: a succession certificate or probate is required. This takes months; start first.`, [limitRef], label);
        }
      } else {
        need('indemnity_bond', label, [limitRef]);
        need('noc_heirs', label, [limitRef]);
        const range = gv ? `${inr(gv.low)}-${inr(gv.high)}` : 'unknown';
        if (limitRule.params.legal_heir_cert_accepted) {
          need('legal_heir_certificate', label, [limitRef, cite('HEIR_CERT_STATE')]);
          addFlag('BOUNDARY', 'warn', `Estimated value ${range} may be above or below the ${inr(limit)} limit; the value on the date documents are submitted decides. Get the legal heir certificate now so both outcomes are covered.`, [limitRef], label);
        } else {
          addFlag('BOUNDARY', 'warn', `Estimated value ${range} may cross the ${inr(limit)} limit in force on ${asOf}. If it does, a succession certificate is required, which takes months.`, [limitRef], label);
        }
      }
    }

    let iepf = a.iepf_status || 'unknown';
    if (iepf === 'unknown' && a.last_dividend_year) {
      const years = Number(asOf.slice(0, 4)) - a.last_dividend_year;
      if (years >= ruleAt(kb.rules, 'IEPF_TRANSFER_7Y', asOf).params.years) iepf = 'likely';
    }
    const inIepf = iepf === 'confirmed' || iepf === 'likely';
    if (inIepf) {
      const stampRef = cite('IEPF_INDEMNITY_STAMP');
      need('iepf5_form', label, [cite('IEPF_TRANSFER_7Y')]);
      need('indemnity_bond', label, [stampRef]);
      addFlag('SURETY', 'info', 'Some companies ask for a surety on the indemnity bond. Find a willing surety before the notary visit.', [cite('INDEMNITY_SURETY')], label);
    }
    if ((a.history || []).includes('iepf5_filed') && !(a.history || []).includes('transmission_done')) {
      addFlag('ORDER', 'block', 'IEPF-5 was filed before transmission. The company will not verify the IEPF claim until transmission is complete; do transmission first.', [cite('IEPF_TRANSMISSION_FIRST')], label);
    }

    // Steps, in the order institutions require
    const holderNames = nameVariants(deceased.pan_name, allDocNames);
    const oldNames = [...new Set([a.company_name_on_doc, nameOn(startCompany, a.held_since), finalName])];
    if (a.mode === 'physical') {
      steps.push({ key: 'confirm_holding', who: 'registrar', text: `Write to the registrar (RTA) of ${finalName}, quoting folio ${a.folio || '(see certificate)'} and certificate ${a.certificate_no || '(see certificate)'}. Ask for the current holding including bonus and split shares, and whether any shares or dividends moved to IEPF. The registrar's figure is final.` });
    } else {
      steps.push({ key: 'confirm_holding', who: 'depository participant', text: `Ask the deceased's depository participant (${a.dp_account || 'see statement'}) for a holding statement as on the date of death.` });
    }
    if (iepf === 'unknown') {
      steps.push({ key: 'iepf_search', who: 'heir', text: `Search the IEPF unclaimed-shares search using these names: ${holderNames.join('; ')}, and these company names: ${oldNames.join('; ')}.`, refs: [cite('IEPF_TRANSFER_7Y')] });
    }
    const locRule = ruleInForce('SEBI_DEMAT_ONLY_LOC');
    steps.push({ key: 'open_demat', who: 'heir', text: 'Open a demat account in the claimant\'s name before starting transmission. Transmitted shares are credited only in demat form.', refs: locRule ? [cite('SEBI_DEMAT_ONLY_LOC')] : [] });
    if (a.mode === 'physical' && a.original_available === false) {
      steps.push({ key: 'duplicate_cert', who: 'registrar', text: `Apply to the registrar of ${finalName} for a duplicate certificate (issued as a Letter of Confirmation).` });
    }
    if (a.mode === 'physical') {
      steps.push({ key: 'transmission', who: 'registrar', text: `Send Form ISR-5 and the documents in the checklist to the registrar of ${finalName}.`, refs: [limitRef] });
    } else {
      steps.push({ key: 'transmission', who: 'depository participant', text: 'Submit the transmission form and the documents in the checklist to the deceased\'s depository participant.', refs: [limitRef] });
    }
    if (inIepf) {
      const firstRef = cite('IEPF_TRANSMISSION_FIRST');
      steps.push({ key: 'entitlement_letter', who: 'company', text: `After transmission, ask ${finalName}'s IEPF nodal officer for the entitlement letter.`, refs: [firstRef] });
      steps.push({ key: 'iepf5_file', who: 'heir', text: 'File e-Form IEPF-5 online with the entitlement letter details. Keep the SRN.', refs: [firstRef] });
      steps.push({ key: 'iepf5_send', who: 'heir', text: `Send the signed IEPF-5 printout, indemnity bond on stamp paper, advance receipt and documents to ${finalName}'s IEPF nodal officer. The IEPF Authority credits the shares to the claimant's demat account.`, refs: [cite('IEPF_INDEMNITY_STAMP')] });
    } else if (a.mode === 'physical' && locRule) {
      steps.push({ key: 'demat_loc', who: 'heir', text: `Within ${locRule.params.loc_valid_days} days of receiving the Letter of Confirmation, give it to your depository participant. After that the shares go to the company's suspense account.`, refs: [cite('SEBI_DEMAT_ONLY_LOC')] });
    }

    return {
      label, kind: 'shares', status, holderMatch: p.holderMatch, resolution, trace,
      value: p.value, threshold, iepf, steps,
    };
  }

  function planDeposit(p) {
    const { a, label } = p;
    const steps = [];
    checkHolder(p);
    const deaRule = ruleAt(kb.rules, 'DEA_TRANSFER_10Y', asOf);
    const refDate = a.type === 'fd' ? a.maturity_date : a.last_activity;
    const years = yearsBetween(refDate, asOf);
    const inDea = years >= deaRule.params.years;
    const deaRef = cite('DEA_TRANSFER_10Y');
    const claimRef = cite('BANK_DECEASED_CLAIM');
    const holderNames = nameVariants(deceased.pan_name, allDocNames);

    if (inDea) {
      const udgamRef = ruleInForce('UDGAM_SEARCH') ? cite('UDGAM_SEARCH') : null;
      const ids = [deceased.pan ? 'PAN' : null, deceased.date_of_birth ? `date of birth ${deceased.date_of_birth}` : null].filter(Boolean);
      const addresses = deceased.addresses || [];
      steps.push({
        key: 'udgam_search', who: 'heir',
        text: `Search UDGAM for ${a.bank} using names: ${holderNames.join('; ')}; identifiers: ${ids.join(', ') || 'none'}; and, if no ID matches, each old address: ${addresses.join(' | ') || 'none known'}. Note the UDRN.`,
        refs: udgamRef ? [udgamRef] : [],
      });
    }
    if (a.staff_denied) {
      addFlag('STAFF_DENIED', 'warn', `Branch staff said this ${a.type === 'fd' ? 'deposit' : 'account'} does not exist. ${inDea ? `It has been inactive ${Math.floor(years)} years, so it has most likely moved to RBI's DEA Fund and is still payable at the same bank.` : 'It is not old enough to be in the DEA Fund; ask for a written reply.'} Print the cited rule and take it to the branch.`, [deaRef], label);
      steps.push({ key: 'print_rule', who: 'heir', text: `Print rule ${deaRef} and the UDGAM result, and ask the branch for its written document list for deceased-depositor claims.`, refs: [deaRef, claimRef] });
    }
    steps.push({
      key: 'bank_claim', who: 'bank',
      text: inDea
        ? `Submit the claim at ${a.bank}${a.branch ? ` (${a.branch} branch)` : ''} quoting the UDRN. The bank pays and reclaims the amount from the DEA Fund.`
        : `Submit a deceased-depositor claim at ${a.bank}${a.branch ? ` (${a.branch} branch)` : ''}. The account is inactive but still with the bank.`,
      refs: [deaRef, claimRef],
    });

    need('death_certificate', label);
    need('claimant_kyc', label);
    need('bank_claim_form', label, [claimRef]);
    if (!a.nominee) {
      addFlag('BANK_DOCS_VARY', 'info', `No nominee: ${a.bank}'s own policy decides the heir documents. Ask for the list in writing; a legal heir certificate obtained for other assets can usually be reused.`, [claimRef], label);
    }

    return {
      label, kind: 'deposit', status: inDea ? 'likely' : 'confirmed', holderMatch: p.holderMatch,
      location: inDea ? 'RBI DEA Fund (claim at the same bank)' : `${a.bank}`,
      yearsInactive: Math.floor(years),
      value: a.amount ? { low: a.amount, high: null, basis: 'principal on document; interest rules apply' } : null,
      steps,
    };
  }

  const documents = finaliseDocuments(docNeeds, input, kb);
  const trips = planTrips(documents, kb);
  for (const d of documents) {
    if (d.long_lead) addFlag('LONG_LEAD', 'warn', `${d.name}: start this first, it can take months.`, [...d.refs]);
  }

  return {
    case_id: input.id,
    title: input.title,
    as_of: asOf,
    assets,
    documents,
    trips,
    flags,
    citations: Object.fromEntries(citations),
  };
}

function finaliseDocuments(docNeeds, input, kb) {
  const all = kb.documents.documents;
  const needs = new Map(docNeeds);
  for (const d of [...needs.values()]) {
    for (const dep of d.deps || []) {
      if (!needs.has(dep)) needs.set(dep, { id: dep, ...all[dep], forAssets: new Set(d.forAssets), refs: new Set() });
    }
  }
  const have = new Set(input.documents_in_hand || []);
  return [...needs.values()].map((d) => ({
    id: d.id,
    name: d.name,
    location: d.location,
    locationLabel: kb.documents.locations[d.location],
    in_person: Boolean(d.in_person),
    have: have.has(d.id),
    copies: d.per_asset_original ? d.forAssets.size : 1,
    forAssets: [...d.forAssets],
    deps: d.deps || [],
    wait_after: d.wait_after || [],
    long_lead: Boolean(d.long_lead),
    people: d.people || null,
    refs: [...d.refs],
  }));
}

// Groups in-person tasks into the fewest half-day trips. A task joins an earlier trip at the
// same place unless it depends on something that needs processing time or a different place.
export function planTrips(documents, kb) {
  const nodes = documents.filter((d) => d.in_person && !d.have);
  const byId = new Map(nodes.map((n) => [n.id, n]));
  const layer = new Map();
  const visit = (n, stack = new Set()) => {
    if (layer.has(n.id)) return layer.get(n.id);
    if (stack.has(n.id)) throw new Error('document dependency cycle');
    stack.add(n.id);
    let l = 0;
    for (const depId of n.deps) {
      const dep = byId.get(depId);
      if (!dep) continue;
      const bump = n.wait_after.includes(depId) || dep.location !== n.location ? 1 : 0;
      l = Math.max(l, visit(dep, stack) + bump);
    }
    layer.set(n.id, l);
    return l;
  };
  nodes.forEach((n) => visit(n));

  const groups = new Map();
  for (const n of nodes) {
    const key = `${layer.get(n.id)}|${n.location}`;
    const g = groups.get(key) || { layer: layer.get(n.id), location: n.location, locationLabel: kb.documents.locations[n.location], tasks: [] };
    g.tasks.push(n.copies > 1 ? `${n.name} (x${n.copies}, one original per institution)` : n.name);
    groups.set(key, g);
  }
  const planned = [...groups.values()].sort((x, y) => x.layer - y.layer || x.location.localeCompare(y.location));
  planned.forEach((g, i) => { g.trip = i + 1; });
  const separate = nodes.reduce((s, n) => s + n.copies, 0);
  return { planned, plannedCount: planned.length, separateErrands: separate };
}

