// Runs every case in cases/ through the deterministic engine and checks it against the
// hand-computed expectations stored in each case. Writes eval/RESULTS.md.

import { writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { buildPlan } from '../src/engine/index.js';
import { loadKnowledge, loadCases, ROOT } from '../src/node/load.js';

function check(plan, expected) {
  const results = [];
  const add = (name, ok, detail = '') => results.push({ name, ok, detail });
  const flagCodes = new Set(plan.flags.map((f) => f.code));
  const docIds = new Set(plan.documents.map((d) => d.id));

  (expected.assets || []).forEach((ea, i) => {
    const a = plan.assets[i];
    if (!a) return add(`asset ${i} exists`, false, 'missing');
    if (ea.company) {
      const got = a.trace?.finalCompanyId || null;
      add(`asset ${i} company`, got === ea.company, `expected ${ea.company}, got ${got}`);
    }
    if (ea.final_name) add(`asset ${i} name`, a.trace?.finalName === ea.final_name, `got ${a.trace?.finalName}`);
    if (ea.status) add(`asset ${i} status`, a.status === ea.status, `expected ${ea.status}, got ${a.status}`);
    if (ea.shares != null) add(`asset ${i} shares`, a.trace?.shares === ea.shares, `expected ${ea.shares}, got ${a.trace?.shares}`);
    if (ea.fractions) {
      const got = (a.trace?.fractions || []).map((f) => f.fraction);
      add(`asset ${i} fractions`, JSON.stringify(got) === JSON.stringify(ea.fractions), `got [${got}]`);
    }
    if (ea.band) add(`asset ${i} threshold band`, a.threshold?.band === ea.band, `expected ${ea.band}, got ${a.threshold?.band}`);
    if (ea.location_contains) add(`asset ${i} location`, (a.location || '').includes(ea.location_contains), `got ${a.location}`);
  });

  for (const c of expected.flags_include || []) add(`flag ${c} raised`, flagCodes.has(c));
  for (const c of expected.flags_exclude || []) add(`flag ${c} not raised`, !flagCodes.has(c));
  for (const d of expected.documents_include || []) add(`document ${d} required`, docIds.has(d));
  for (const d of expected.documents_exclude || []) add(`document ${d} not required`, !docIds.has(d));

  const stepKeys = plan.assets.flatMap((a) => a.steps.map((s) => s.key));
  for (const k of expected.steps_include || []) add(`step ${k} present`, stepKeys.includes(k));
  for (const k of expected.steps_exclude || []) add(`step ${k} absent`, !stepKeys.includes(k));
  for (const [first, then] of expected.order || []) {
    const i = stepKeys.indexOf(first);
    const j = stepKeys.indexOf(then);
    add(`order ${first} before ${then}`, i >= 0 && j >= 0 && i < j, `positions ${i}, ${j}`);
  }
  if (expected.max_trips != null) {
    add(`at most ${expected.max_trips} trips`, plan.trips.plannedCount <= expected.max_trips, `planned ${plan.trips.plannedCount}`);
  }
  return results;
}

const kb = loadKnowledge();
const cases = loadCases();
const rows = [];
let totalChecks = 0;
let passedChecks = 0;

for (const c of cases) {
  let plan;
  let results;
  try {
    plan = buildPlan(c, kb);
    results = check(plan, c.expected);
  } catch (err) {
    results = [{ name: 'engine ran', ok: false, detail: err.message }];
  }
  const passed = results.filter((r) => r.ok).length;
  totalChecks += results.length;
  passedChecks += passed;
  const failures = results.filter((r) => !r.ok);
  rows.push({ c, plan, passed, total: results.length, failures });
  const mark = failures.length ? 'FAIL' : 'PASS';
  console.log(`${mark}  ${c.id}  ${passed}/${results.length}  ${c.title}`);
  for (const f of failures) console.log(`        x ${f.name}${f.detail ? ` (${f.detail})` : ''}`);
}

const casesPassed = rows.filter((r) => !r.failures.length).length;
console.log(`\n${casesPassed}/${rows.length} cases fully pass; ${passedChecks}/${totalChecks} checks pass.`);

const md = [
  '# Evaluation results (deterministic engine)',
  '',
  `Generated by \`npm run eval\`. ${casesPassed}/${rows.length} cases fully pass; ${passedChecks}/${totalChecks} individual checks pass.`,
  '',
  'Expectations were computed by hand from the cited sources before running the engine (see `why` in each case file).',
  '',
  '| Case | Result | Checks | What it tests | Engine output |',
  '|---|---|---|---|---|',
  ...rows.map(({ c, plan, passed, total, failures }) => {
    const a = plan?.assets?.[0];
    const out = a
      ? a.kind === 'shares'
        ? `${a.status}; ${a.trace?.shares ?? '-'} shares of ${a.trace?.finalName ?? '?'}; band ${a.threshold?.band ?? '-'}; ${plan.trips.plannedCount} trip(s)`
        : `${a.status}; ${a.location}; ${plan.trips.plannedCount} trip(s)`
      : 'error';
    return `| ${c.id} | ${failures.length ? '**FAIL**' : 'pass'} | ${passed}/${total} | ${c.title} | ${out} |`;
  }),
  '',
  '## Failures',
  '',
  ...(rows.some((r) => r.failures.length)
    ? rows.filter((r) => r.failures.length).flatMap(({ c, failures }) => [
        `**${c.id}: ${c.title}**`,
        '',
        ...failures.map((f) => `- ${f.name}${f.detail ? ` (${f.detail})` : ''}`),
        '',
        `Why this was expected: ${c.expected.why}`,
        '',
      ])
    : ['None.']),
];
writeFileSync(join(ROOT, 'eval', 'RESULTS.md'), md.join('\n') + '\n');

