// Deterministic speckle noise so images are identical on every run.
function noiseOverlay(width, height, seed, amount) {
  let s = seed;
  const rand = () => ((s = (s * 1664525 + 1013904223) >>> 0) / 4294967296);
  const buf = Buffer.alloc(width * height * 4);
  for (let i = 0; i < width * height; i++) {
    const v = rand() < amount ? Math.floor(rand() * 120) : 0;
    buf[i * 4] = 60; buf[i * 4 + 1] = 45; buf[i * 4 + 2] = 30; buf[i * 4 + 3] = v;
  }
  return sharp(buf, { raw: { width, height, channels: 4 } }).png().toBuffer();
}

async function render(file, svg, { rotate = 0, blur = 0, brightness = 1, saturation = 1, noise = 0, quality = 80, seed = 1 } = {}) {
  const base = sharp(Buffer.from(svg)).flatten({ background: '#ffffff' });
  const { width, height } = await base.metadata();
  let img = sharp(await base.png().toBuffer());
  if (noise) img = img.composite([{ input: await noiseOverlay(width, height, seed, noise) }]);
  img = sharp(await img.png().toBuffer()).modulate({ brightness, saturation });
  if (blur) img = img.blur(blur);
  if (rotate) img = img.rotate(rotate, { background: '#3b3b3b' });
  await img.jpeg({ quality }).toFile(join(OUT, file));
}

