// Step 1 of the pipeline: a vision LLM reads each synthetic document photo and returns fields
// with a confidence per field. Scores the output against ground truth and writes
// eval/EXTRACTION.md. Needs OPENROUTER_API_KEY (env or .env). Usage:
//   npm run extract                      (default free model)
//   npm run extract -- --model nvidia/nemotron-3.5-super-vl:free

import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
import { join } from 'node:path';
import { ROOT, readJson } from '../src/node/load.js';

const DEFAULT_MODEL = 'google/gemma-4-31b-it:free';
const CONFIDENT = 0.8;

function apiKey() {
  if (process.env.OPENROUTER_API_KEY) return process.env.OPENROUTER_API_KEY;
  const envFile = join(ROOT, '.env');
  if (existsSync(envFile)) {
    const m = readFileSync(envFile, 'utf8').match(/^OPENROUTER_API_KEY\s*=\s*(.+)$/m);
    if (m) return m[1].trim();
  }
  return null;
}

const argModel = process.argv.indexOf('--model');
const model = argModel > 0 ? process.argv[argModel + 1] : process.env.OPENROUTER_MODEL || DEFAULT_MODEL;

const PROMPT = `You are reading a photo of an Indian financial document (share certificate, demat statement, fixed deposit receipt, bank passbook, dividend warrant, or a handwritten note).

Return ONLY a JSON object with this shape:
{
  "doc_type": "share_certificate" | "demat_statement" | "fixed_deposit_receipt" | "passbook" | "dividend_warrant" | "note" | "unknown",
  "fields": {
    "<field>": { "value": <string|number|null>, "confidence": <0..1> }
  }
}

Fields to extract when present: company_name, holder_name, holder_name_latin, folio, certificate_no, shares, face_value, date, dp_id, bank, branch, amount, deposit_date, maturity_date, receipt_no, account_no, last_transaction_date, balance, address.

Rules:
- Copy names exactly as written, including initials and honorifics. Do not expand abbreviations.
- If a name is not in Latin script, put it as written in holder_name and a romanised form in holder_name_latin.
- Dates as YYYY-MM-DD (or YYYY if only the year is written). Amounts and share counts as plain numbers.
- Do not work out successor companies, current values or anything not written on the document.
- If a field is unreadable, set value to null. A null is better than a guess.`;

async function callModel(key, imagePath) {
  const b64 = readFileSync(imagePath).toString('base64');
  const body = {
    model,
    temperature: 0,
    messages: [{
      role: 'user',
      content: [
        { type: 'text', text: PROMPT },
        { type: 'image_url', image_url: { url: `data:image/jpeg;base64,${b64}` } },
      ],
    }],
  };
  for (let attempt = 0; attempt < 5; attempt++) {
    const res = await fetch('https://openrouter.ai/api/v1/chat/completions', {
      method: 'POST',
      headers: { Authorization: `Bearer ${key}`, 'Content-Type': 'application/json', 'X-Title': 'Virasat prototype' },
      body: JSON.stringify(body),
    });
    if (res.status === 429 || res.status >= 500) {
      const wait = 5000 * (attempt + 1);
      console.log(`  ${res.status}, retrying in ${wait / 1000}s`);
      await new Promise((r) => setTimeout(r, wait));
      continue;
    }
    const json = await res.json();
    if (!res.ok) throw new Error(`${res.status}: ${JSON.stringify(json).slice(0, 300)}`);
    return json.choices?.[0]?.message?.content || '';
  }
  throw new Error('rate limited after retries');
}

function parseJson(text) {
  const m = text.match(/\{[\s\S]*\}/);
  if (!m) return null;
  try { return JSON.parse(m[0]); } catch { return null; }
}

const normText = (s) => String(s).toUpperCase().normalize('NFC').replace(/[^\p{L}\p{N}]+/gu, '');
function normNumber(v) {
  const n = Number(String(v).replace(/[^0-9.]/g, ''));
  return Number.isFinite(n) ? n : null;
}
function same(field, truth, got) {
  if (got == null || got === '') return false;
  if (typeof truth === 'number') return normNumber(got) === truth;
  if (/date/.test(field) || field === 'date') return String(got).slice(0, String(truth).length) === String(truth);
  return normText(truth) === normText(got);
}

async function main() {
  const key = apiKey();
  if (!key) {
    console.error('No OPENROUTER_API_KEY found. Create a free key at https://openrouter.ai/keys and put it in .env as OPENROUTER_API_KEY=...');
    process.exit(1);
  }
  const { documents } = readJson('cases', 'docs', 'ground_truth.json');
  const slug = model.replace(/[^a-z0-9.-]+/gi, '_');
  const outDir = join(ROOT, 'eval', 'extraction', slug);
  mkdirSync(outDir, { recursive: true });

  const rows = [];
  for (const [file, truth] of Object.entries(documents)) {
    process.stdout.write(`${file} ... `);
    let raw = '';
    let parsed = null;
    let error = null;
    try {
      raw = await callModel(key, join(ROOT, 'cases', 'docs', file));
      parsed = parseJson(raw);
      if (!parsed) error = 'response was not valid JSON';
    } catch (e) {
      error = e.message;
    }
    writeFileSync(join(outDir, file.replace(/\.jpg$/, '.json')), JSON.stringify({ model, file, raw, parsed, error }, null, 2));

    const fields = Object.keys(truth).filter((f) => !['doc_type', 'expect_abstain'].includes(f));
    const detail = fields.map((f) => {
      const got = parsed?.fields?.[f];
      const value = got && typeof got === 'object' ? got.value : got;
      const confidence = got && typeof got === 'object' ? Number(got.confidence) : null;
      const correct = same(f, truth[f], value);
      const abstained = value == null || value === '';
      return { field: f, truth: truth[f], value, confidence, correct, abstained, confidentWrong: !correct && !abstained && confidence >= CONFIDENT };
    });
    const correct = detail.filter((d) => d.correct).length;
    const abstained = detail.filter((d) => d.abstained).length;
    const confidentWrong = detail.filter((d) => d.confidentWrong);
    rows.push({ file, truth, detail, correct, abstained, confidentWrong, total: fields.length, error });
    console.log(error ? `error: ${error}` : `${correct}/${fields.length} correct, ${abstained} null, ${confidentWrong.length} confident-wrong`);
    await new Promise((r) => setTimeout(r, 3500));
  }

  const scored = rows.filter((r) => !r.error);
  const tot = scored.reduce((s, r) => s + r.total, 0);
  const cor = scored.reduce((s, r) => s + r.correct, 0);
  const cw = scored.reduce((s, r) => s + r.confidentWrong.length, 0);
  const md = [
    `# Extraction results: ${model}`,
    '',
    `Run on ${new Date().toISOString().slice(0, 10)} over ${rows.length} synthetic document photos (\`npm run extract\`). Temperature 0.`,
    '',
    `- Fields correct: **${cor}/${tot}** (${tot ? Math.round((100 * cor) / tot) : 0}%) across ${scored.length} documents that returned valid JSON.`,
    `- Confident-wrong fields (wrong value with confidence >= ${CONFIDENT}): **${cw}**. These are the dangerous ones; the heir-confirmation step exists to catch them.`,
    `- Documents with errors or invalid JSON: ${rows.length - scored.length}.`,
    '',
    '| Document | Correct | Null | Confident-wrong | Notes |',
    '|---|---|---|---|---|',
    ...rows.map((r) => {
      const notes = r.error
        ? r.error
        : [...r.detail.filter((d) => !d.correct).map((d) => `${d.field}: got ${JSON.stringify(d.value)} (conf ${d.confidence ?? '-'}), truth ${JSON.stringify(d.truth)}`)].join('; ') || '-';
      const abstainNote = r.truth.expect_abstain ? ' (deliberately unreadable: nulls are the right answer)' : '';
      return `| ${r.file}${abstainNote} | ${r.correct}/${r.total} | ${r.abstained} | ${r.confidentWrong.length} | ${notes.replace(/\|/g, '/')} |`;
    }),
    '',
    'Raw model responses are saved next to this file under `eval/extraction/`.',
  ];
  writeFileSync(join(ROOT, 'eval', 'EXTRACTION.md'), md.join('\n') + '\n');
  console.log(`\n${cor}/${tot} fields correct; ${cw} confident-wrong. Wrote eval/EXTRACTION.md`);
}

main();

// Minimal static server for the demo: npm run demo, then open http://localhost:5173
import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { join, normalize, extname } from 'node:path';
import { ROOT } from '../src/node/load.js';

const TYPES = { '.html': 'text/html', '.js': 'text/javascript', '.json': 'application/json', '.css': 'text/css', '.jpg': 'image/jpeg', '.png': 'image/png', '.md': 'text/markdown' };
const PORT = Number(process.env.PORT) || 5173;

createServer(async (req, res) => {
  const urlPath = decodeURIComponent(new URL(req.url, 'http://x').pathname);
  const file = normalize(join(ROOT, urlPath === '/' ? 'index.html' : urlPath));
  if (!file.startsWith(ROOT) || file.includes('node_modules') || file.endsWith('.env')) {
    res.writeHead(403).end();
    return;
  }
  try {
    const body = await readFile(file);
    res.writeHead(200, { 'Content-Type': TYPES[extname(file)] || 'application/octet-stream' }).end(body);
  } catch {
    res.writeHead(404).end('not found');
  }
}).listen(PORT, () => console.log(`Virasat demo on http://localhost:${PORT}`));

