const caseIds = await getJson('cases/index.json');
const cases = await Promise.all(caseIds.map((id) => getJson(`cases/${id}.json`)));

const select = $('#case-select');
select.innerHTML = cases.map((c, i) => `<option value="${i}">${esc(c.id)}: ${esc(c.title)}</option>`).join('');

const SHARE_FIELDS = [
  ['company_name_on_doc', 'Company name on document', 'text'],
  ['holder_name_on_doc', 'Holder name on document', 'text'],
  ['shares', 'Number of shares', 'number'],
  ['face_value', 'Face value (Rs)', 'number'],
  ['held_since', 'Certificate / statement date', 'date'],
  ['folio', 'Folio', 'text'],
  ['mode', 'Holding', 'select:physical,demat'],
  ['nominee', 'Nominee registered', 'checkbox'],
  ['iepf_status', 'Shares in IEPF?', 'select:unknown,confirmed,no'],
];
const DEPOSIT_FIELDS = [
  ['bank', 'Bank', 'text'],
  ['branch', 'Branch', 'text'],
  ['holder_name_on_doc', 'Holder name on document', 'text'],
  ['amount', 'Amount (Rs)', 'number'],
  ['maturity_date', 'Maturity date (FD)', 'date'],
  ['last_activity', 'Last transaction (savings)', 'date'],
  ['nominee', 'Nominee registered', 'checkbox'],
  ['staff_denied', 'Branch staff said "no such account"', 'checkbox'],
];

let current = null;

function field(name, label, type, value, prefix) {
  const id = `${prefix}${name}`;
  if (type === 'checkbox') {
    return `<label class="field check"><input type="checkbox" id="${id}" data-key="${name}" ${value ? 'checked' : ''}> ${esc(label)}</label>`;
  }
  if (type.startsWith('select:')) {
    const opts = type.slice(7).split(',');
    return `<label class="field"><span>${esc(label)}</span><select id="${id}" data-key="${name}">${opts.map((o) => `<option ${o === value ? 'selected' : ''}>${o}</option>`).join('')}</select></label>`;
  }
  return `<label class="field"><span>${esc(label)}</span><input type="${type}" id="${id}" data-key="${name}" value="${esc(value ?? '')}"></label>`;
}

function loadCase(i) {
  current = structuredClone(cases[i]);
  const a = current.assets[0];
  $('#doc-image').innerHTML = a.image
    ? `<figure><img src="cases/docs/${esc(a.image)}" alt="Synthetic document photo"><figcaption>Synthetic document photo (${esc(a.image)})</figcaption></figure>`
    : '<p class="hint">No photo for this case; facts come from a statement.</p>';
  const fields = a.kind === 'shares' ? SHARE_FIELDS : DEPOSIT_FIELDS;
  $('#facts-form').innerHTML = `
    <div class="grid">
      ${field('as_of', 'Claim date (rules apply as of)', 'date', current.as_of, 'c_')}
      ${field('pan_name', "Deceased's name on PAN", 'text', current.deceased.pan_name, 'd_')}
    </div>
    <h3>${a.kind === 'shares' ? 'Share holding' : 'Bank deposit'}</h3>
    <div class="grid">${fields.map(([k, l, t]) => field(k, l, t, a[k], 'a_')).join('')}</div>
    <p class="hint why"><b>What this case tests:</b> ${esc(current.expected?.why || '')}</p>`;
  $('#plan').innerHTML = '<p class="empty">Confirm the facts to build the plan.</p>';
  $('#print-btn').hidden = true;
}

function readForm() {
  const input = structuredClone(current);
  input.as_of = $('#c_as_of').value;
  input.deceased.pan_name = $('#d_pan_name').value;
  const a = input.assets[0];
  for (const el of document.querySelectorAll('#facts-form [id^="a_"]')) {
    const k = el.dataset.key;
    if (el.type === 'checkbox') a[k] = el.checked;
    else if (el.type === 'number') a[k] = el.value === '' ? null : Number(el.value);
    else a[k] = el.value || null;
  }
  return input;
}

const STATUS_TEXT = {
  confirmed: 'Confirmed by cited events',
  likely: 'Likely: needs confirmation',
  unknown: 'Unknown: not guessed',
  doubtful: 'Doubtful',
};

function renderAsset(a) {
  const path = (a.trace?.path || []).map((p) => `
    <li><span class="date">${esc(p.date)}</span> ${esc(p.text)}
      <a class="src" href="${esc(p.source.url)}" target="_blank" rel="noopener">${esc(p.source.title)}</a></li>`).join('');
  const value = a.value
    ? `<div class="kv"><span>Estimated value</span><b>${inr(a.value.low)}${a.value.high ? ` to ${inr(a.value.high)}` : '+'}</b><small>${esc(a.value.basis)}</small></div>`
    : '';
  const thr = a.threshold
    ? `<div class="kv"><span>SEBI limit</span><b>${a.threshold.band} vs ${inr(a.threshold.limit)}</b><small>${esc(a.threshold.rule)}</small></div>`
    : '';
  const today = a.trace && a.status !== 'doubtful'
    ? `<div class="kv big"><span>Holding today</span><b>${a.trace.shares.toLocaleString('en-IN')} shares of ${esc(a.trace.finalName)}</b></div>` : '';
  const where = a.location ? `<div class="kv big"><span>Held by</span><b>${esc(a.location)}</b><small>inactive ${a.yearsInactive} years</small></div>` : '';
  const match = a.resolution
    ? `<div class="kv"><span>Company match</span><b>${esc(a.resolution.decision)}: ${esc(a.resolution.top.matchedName)}</b><small>score ${a.resolution.top.score}</small></div>` : '';
  const name = `<div class="kv"><span>Holder name</span><b>${esc(a.holderMatch.kind)}</b><small>score ${a.holderMatch.score}</small></div>`;
  const steps = a.steps.map((s) => `<li><span class="who">${esc(s.who)}</span> ${esc(s.text)} ${(s.refs || []).map((r) => `<span class="ref">${esc(r)}</span>`).join(' ')}</li>`).join('');
  return `
    <article class="asset">
      <header><h3>${esc(a.label)}</h3><span class="badge ${a.status}">${STATUS_TEXT[a.status] || a.status}</span></header>
      <div class="kvs">${today}${where}${value}${thr}${match}${name}</div>
      ${path ? `<h4>How the holding changed (every step cited)</h4><ol class="path">${path}</ol>` : ''}
      <h4>Steps, in the order institutions require</h4>
      <ol class="steps">${steps}</ol>
    </article>`;
}

function renderPlan(plan) {
  const flags = plan.flags.map((f) => `<li class="flag ${f.severity}"><b>${esc(f.code)}</b> ${esc(f.message)} ${f.refs.map((r) => `<span class="ref">${esc(r)}</span>`).join(' ')}</li>`).join('');
  const docs = plan.documents
    .sort((x, y) => Number(y.in_person) - Number(x.in_person))
    .map((d) => `<li class="${d.have ? 'have' : ''}"><input type="checkbox" ${d.have ? 'checked' : ''} disabled> ${esc(d.name)}${d.copies > 1 ? ` <b>x${d.copies}</b>` : ''} <small>${esc(d.locationLabel)}${d.people ? `, needs: ${esc(d.people)}` : ''}</small></li>`).join('');
  const trips = plan.trips.planned.map((t) => `<li><b>Trip ${t.trip}: ${esc(t.locationLabel)}</b><ul>${t.tasks.map((x) => `<li>${esc(x)}</li>`).join('')}</ul></li>`).join('');
  const cites = Object.entries(plan.citations).map(([ref, c]) => `
    <li><b>${esc(ref)}</b> <span class="kind ${c.kind}">${esc(c.kind)}</span> ${esc(c.summary)}
      <br><small>${c.source.url ? `<a href="${esc(c.source.url)}" target="_blank" rel="noopener">${esc(c.source.title)}</a>` : esc(c.source.title)} · in force from ${esc(c.effective_from)}${c.effective_to ? ` to ${esc(c.effective_to)}` : ''}</small></li>`).join('');
  return `
    <p class="meta">Rules applied as of <b>${esc(plan.as_of)}</b>.</p>
    ${plan.assets.map(renderAsset).join('')}
    ${flags ? `<h3>Checks before anything is posted</h3><ul class="flags">${flags}</ul>` : ''}
    <h3>Document checklist</h3><ul class="docs">${docs}</ul>
    <h3>Trip plan: ${plan.trips.plannedCount} half-day trip(s) instead of ${plan.trips.separateErrands} separate errands</h3>
    ${trips ? `<ol class="trips">${trips}</ol>` : '<p class="hint">No in-person visits needed.</p>'}
    <h3>Sources for every rule used</h3><ul class="cites">${cites}</ul>`;
}

$('#confirm-btn').addEventListener('click', () => {
  try {
    const plan = buildPlan(readForm(), kb);
    $('#plan').innerHTML = renderPlan(plan);
    $('#print-btn').hidden = false;
  } catch (e) {
    $('#plan').innerHTML = `<p class="flag block">Could not build a plan: ${esc(e.message)}</p>`;
  }
});
$('#print-btn').addEventListener('click', () => window.print());
select.addEventListener('change', () => loadCase(Number(select.value)));

const start = Math.max(0, caseIds.indexOf(new URLSearchParams(location.search).get('case') || 'case08'));
select.value = String(start);
loadCase(start);

:root {
  --ink: #1d2433;
  --muted: #5d6677;
  --line: #dde2ea;
  --bg: #f5f6f8;
  --card: #fff;
  --accent: #1f4e8c;
  --ok: #1d7a46;
  --warn: #a35b00;
  --bad: #b3261e;
  --info: #3d5a80;
}
* { box-sizing: border-box; }
body { margin: 0; font: 15px/1.5 system-ui, -apple-system, "Segoe UI", sans-serif; color: var(--ink); background: var(--bg); }
.top { display: flex; justify-content: space-between; align-items: center; gap: 16px; padding: 16px 24px; background: #fff; border-bottom: 1px solid var(--line); }
.top h1 { margin: 0; font-size: 24px; color: var(--accent); }
.tag { margin: 2px 0 0; color: var(--muted); }
.case-pick { display: flex; flex-direction: column; font-size: 13px; color: var(--muted); }
.case-pick select { margin-top: 4px; padding: 6px; min-width: 360px; font-size: 14px; }
.layout { display: grid; grid-template-columns: minmax(340px, 5fr) 7fr; gap: 16px; padding: 16px 24px; align-items: start; }
.panel { background: var(--card); border: 1px solid var(--line); border-radius: 10px; padding: 16px 18px; }
.panel h2 { margin: 0 0 8px; font-size: 18px; }
.step-no { display: inline-block; background: var(--accent); color: #fff; border-radius: 4px; padding: 0 6px; font-size: 12px; margin-right: 6px; vertical-align: 2px; }
.hint { color: var(--muted); font-size: 13px; }
.why { background: #f2f5fa; padding: 8px 10px; border-radius: 6px; }
figure { margin: 8px 0 12px; }
figure img { width: 100%; border-radius: 6px; border: 1px solid var(--line); }
figcaption { font-size: 12px; color: var(--muted); }
.grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px 12px; }
.field { display: flex; flex-direction: column; font-size: 12px; color: var(--muted); }
.field input, .field select { margin-top: 2px; padding: 6px 8px; font-size: 14px; border: 1px solid var(--line); border-radius: 6px; color: var(--ink); }
.field.check { flex-direction: row; align-items: center; gap: 6px; font-size: 13px; color: var(--ink); }
h3 { font-size: 15px; margin: 18px 0 8px; }
h4 { font-size: 13px; margin: 14px 0 6px; color: var(--muted); text-transform: uppercase; letter-spacing: .03em; }
button.primary { margin-top: 14px; width: 100%; padding: 10px; background: var(--accent); color: #fff; border: 0; border-radius: 8px; font-size: 15px; cursor: pointer; }
button.ghost { background: none; border: 1px solid var(--line); border-radius: 6px; padding: 6px 10px; cursor: pointer; }
.plan-head { display: flex; justify-content: space-between; align-items: center; }
.empty { color: var(--muted); }
.meta { color: var(--muted); margin-top: 0; }
.asset { border: 1px solid var(--line); border-radius: 8px; padding: 12px 14px; margin-bottom: 12px; }
.asset header { display: flex; justify-content: space-between; align-items: center; gap: 8px; }
.asset h3 { margin: 0; }
.badge { font-size: 12px; padding: 2px 8px; border-radius: 999px; white-space: nowrap; }
.badge.confirmed { background: #e3f4ea; color: var(--ok); }
.badge.likely { background: #fff1dc; color: var(--warn); }
.badge.unknown, .badge.doubtful { background: #fde8e7; color: var(--bad); }
.kvs { display: grid; grid-template-columns: repeat(auto-fill, minmax(180px, 1fr)); gap: 8px; margin-top: 10px; }
.kv { background: #f7f8fa; border-radius: 6px; padding: 6px 8px; display: flex; flex-direction: column; }
.kv.big { grid-column: 1 / -1; }
.kv.big b { font-size: 18px; }
.kv span { font-size: 11px; color: var(--muted); text-transform: uppercase; }
.kv small { color: var(--muted); font-size: 12px; }
.path, .steps, .trips { padding-left: 20px; }
.path li, .steps li { margin-bottom: 6px; }
.date { font-family: Consolas, monospace; background: #eef1f6; padding: 0 4px; border-radius: 3px; }
.src { display: block; font-size: 12px; color: var(--accent); }
.who { display: inline-block; font-size: 11px; text-transform: uppercase; background: #eef1f6; padding: 0 6px; border-radius: 3px; color: var(--muted); }
.ref { font-size: 11px; font-family: Consolas, monospace; color: var(--accent); background: #edf2fb; padding: 0 4px; border-radius: 3px; }
.flags, .docs, .cites { list-style: none; padding: 0; }
.flag { padding: 8px 10px; border-radius: 6px; margin-bottom: 6px; border-left: 4px solid; }
.flag.block { background: #fde8e7; border-color: var(--bad); }
.flag.warn { background: #fff4e2; border-color: var(--warn); }
.flag.info { background: #eef3fa; border-color: var(--info); }
.docs li { padding: 4px 0; border-bottom: 1px dashed var(--line); }
.docs li.have { color: var(--muted); }
.docs small { color: var(--muted); }
.cites li { margin-bottom: 8px; font-size: 13px; }
.kind { font-size: 11px; padding: 0 5px; border-radius: 3px; }
.kind.regulation { background: #e3f4ea; color: var(--ok); }
.kind.practice { background: #fff1dc; color: var(--warn); }
.foot { padding: 12px 24px 24px; color: var(--muted); font-size: 13px; }
@media (max-width: 900px) { .layout { grid-template-columns: 1fr; } .case-pick select { min-width: 0; } }
@media print {
  .top select, #facts-panel, .foot, #print-btn { display: none; }
  .layout { display: block; padding: 0; }
  .panel { border: 0; }
  body { background: #fff; }
}

{
  "name": "virasat-prototype",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "description": "Virasat prototype: turns a family's old share certificates and deposit receipts into an ordered, cited claim plan.",
  "engines": {
    "node": ">=18"
  },
  "scripts": {
    "start": "node run.mjs",
    "llm": "node run.mjs --llm"
  }
}

const gcd = (a, b) => {
  a = a < 0n ? -a : a;
  b = b < 0n ? -b : b;
  while (b) [a, b] = [b, a % b];
  return a;
};

// Exact fractions on BigInt, so share counts never pick up floating-point error.
export class Frac {
  constructor(n, d = 1n) {
    n = BigInt(n);
    d = BigInt(d);
    if (d === 0n) throw new Error('Fraction with zero denominator');
    if (d < 0n) [n, d] = [-n, -d];
    const g = gcd(n, d) || 1n;
    this.n = n / g;
    this.d = d / g;
  }

  static parse(text) {
    const [n, d = '1'] = String(text).split('/');
    return new Frac(n.trim(), d.trim());
  }

  add(o) { return new Frac(this.n * o.d + o.n * this.d, this.d * o.d); }
  sub(o) { return new Frac(this.n * o.d - o.n * this.d, this.d * o.d); }
  mul(o) { return new Frac(this.n * o.n, this.d * o.d); }

  // Holdings are never negative, so BigInt truncation is a floor here.
  floor() { return new Frac(this.n / this.d); }
  isZero() { return this.n === 0n; }
  toNumber() { return Number(this.n) / Number(this.d); }
  toString() { return this.d === 1n ? `${this.n}` : `${this.n}/${this.d}`; }
}

import { Frac } from './rational.mjs';

// Walks every corporate event after the certificate date and returns today's holding,
// with one trail entry per event so each number can be traced to its source filing.
export function resolveHolding(lineage, companyId, shares, certificateDate) {
  let company = companyId;
  let qty = new Frac(shares);
  let after = certificateDate;
  const trail = [];
  const fractions = [];

  for (;;) {
    const event = lineage.events
      .filter((e) => (e.company === company || e.from === company) && e.date > after)
      .sort((a, b) => a.date.localeCompare(b.date))[0];
    if (!event) break;

    const before = { company, shares: qty.toString() };

    if (event.type === 'struck_off') {
      trail.push({ event, before, after: null });
      return { status: 'struck_off', company, shares: null, fractions, trail };
    }

    if (event.type === 'rename') {
      company = event.to;
    } else if (event.type === 'split') {
      qty = qty.mul(Frac.parse(event.ratio));
    } else if (event.type === 'bonus' || event.type === 'merger') {
      const ratio = Frac.parse(event.ratio);
      const raw = event.type === 'bonus' ? qty.add(qty.mul(ratio)) : qty.mul(ratio);
      const whole = raw.floor();
      const part = raw.sub(whole);
      if (event.type === 'merger') company = event.to;
      if (!part.isZero()) fractions.push({ company, shares: part.toString(), event: event.id });
      qty = whole;
    } else {
      throw new Error(`Unknown corporate event type "${event.type}" in ${event.id}`);
    }

    trail.push({ event, before, after: { company, shares: qty.toString() } });
    after = event.date;
  }

  return { status: 'live', company, shares: qty, fractions, trail };
}

// Returns the single rule version in force on `date`. Zero or two matches is a data error,
// not something to guess around.
export function getRule(rules, id, date, state) {
  const matches = rules.filter(
    (r) =>
      r.id === id &&
      (!r.state || r.state === state) &&
      r.effective_from <= date &&
      (!r.effective_to || date <= r.effective_to),
  );
  if (matches.length !== 1) {
    throw new Error(`Expected one version of rule "${id}" on ${date}${state ? ` in ${state}` : ''}, found ${matches.length}`);
  }
  return matches[0];
}

export const isOverdue = (rule, today) => Boolean(rule.review_by) && rule.review_by < today;

const HONORIFICS = new Set(['SHRI', 'SRI', 'SMT', 'MR', 'MRS', 'MS', 'LATE', 'KUMARI', 'DR']);
const COMPANY_NOISE = new Set(['THE', 'LIMITED', 'LTD', 'CO', 'COMPANY', 'PVT', 'PRIVATE', 'AND', 'OF']);

export const PERSON_AUTO_ACCEPT = 0.85;
export const COMPANY_AUTO_ACCEPT = 0.92;
export const COMPANY_UNKNOWN_BELOW = 0.7;

function levenshtein(a, b) {
  const row = Array.from({ length: b.length + 1 }, (_, j) => j);
  for (let i = 1; i <= a.length; i++) {
    let prev = row[0];
    row[0] = i;
    for (let j = 1; j <= b.length; j++) {
      const tmp = row[j];
      row[j] = Math.min(row[j] + 1, row[j - 1] + 1, prev + (a[i - 1] === b[j - 1] ? 0 : 1));
      prev = tmp;
    }
  }
  return row[b.length];
}

const similarity = (a, b) => (a || b ? 1 - levenshtein(a, b) / Math.max(a.length, b.length) : 1);

const personTokens = (name) =>
  name.toUpperCase().replace(/[.,]/g, ' ').split(/\s+/).filter((t) => t && !HONORIFICS.has(t));

export const normalizeCompany = (name) =>
  name
    .toUpperCase()
    .replace(/&/g, ' AND ')
    .replace(/[^A-Z0-9 ]/g, ' ')
    .split(/\s+/)
    .filter((t) => t && !COMPANY_NOISE.has(t))
    .join(' ');

// Compares the holder name on an old document with the deceased person's PAN name.
export function matchPerson(documentName, panName) {
  const a = personTokens(documentName);
  const b = personTokens(panName);
  if (a.join(' ') === b.join(' ')) return { kind: 'exact', score: 1, needsHuman: false };

  const sameSurname = a.at(-1) === b.at(-1);
  const restA = a.slice(0, -1);
  const restB = b.slice(0, -1);
  const initialsFit =
    sameSurname &&
    restA.length === restB.length &&
    restA.every((t, i) => (t.length === 1 ? restB[i].startsWith(t) : t === restB[i]));

  if (initialsFit) {
    const score = 0.9;
    return { kind: 'initials_consistent', score, needsHuman: score < PERSON_AUTO_ACCEPT };
  }
  const score = similarity(a.join(' '), b.join(' '));
  return { kind: 'fuzzy', score, needsHuman: score < PERSON_AUTO_ACCEPT };
}

// Finds the company in the lineage graph by its name or any known alias.
export function matchCompany(name, lineage) {
  const query = normalizeCompany(name);
  const ranked = Object.entries(lineage.companies)
    .map(([id, c]) => ({
      id,
      score: Math.max(...[c.name, ...(c.aliases ?? [])].map((n) => similarity(query, normalizeCompany(n)))),
    }))
    .sort((x, y) => y.score - x.score);
  const best = ranked[0];
  const decision =
    best.score >= COMPANY_AUTO_ACCEPT ? 'accept' : best.score >= COMPANY_UNKNOWN_BELOW ? 'needs_human' : 'unknown';
  return { decision, best, candidates: ranked.slice(0, 3) };
}

