import { readFileSync, writeFileSync, mkdirSync, copyFileSync } from 'node:fs';
import { join } from 'node:path';

const SRC = 'C:/Users/sujal/.cursor/projects/c-Users-sujal-random/agent-transcripts';
const OUT = 'C:/Users/sujal/tresata-llm-logs/out';
const CHATS = [
  ['31bed4bc-177c-40f5-86c0-9c084a778ace', '02_Rajesh_persona_chat'],
  ['42c72fcd-9f1a-4153-9d45-ef94202d088f', '01_Main_chat_assignment_brief_prototype_video'],
];

mkdirSync(OUT, { recursive: true });

const shorten = (s, n = 300) => (s.length > n ? `${s.slice(0, n)}…` : s);
const toolSummary = (t) => {
  const i = t.input ?? {};
  const main = i.command ?? i.path ?? i.pattern ?? i.glob_pattern ?? i.search_term ?? i.arguments?.search_term ?? i.toolName ?? '';
  return `> Tool: **${t.name}** ${main ? `\`${shorten(String(main).replace(/\s+/g, ' '), 200)}\`` : ''}`;
};

for (const [id, name] of CHATS) {
  const file = join(SRC, id, `${id}.jsonl`);
  const lines = readFileSync(file, 'utf8').split('\n').filter(Boolean).map((l) => JSON.parse(l));
  const md = [`# ${name.replace(/_/g, ' ')}`, '', `Cursor agent chat (model: Claude). Transcript id: ${id}. Exported ${new Date().toISOString().slice(0, 10)}.`, '', 'Tool calls are summarised in one line each; tool outputs are not stored in the transcript.', ''];
  for (const entry of lines) {
    if (!entry.role) continue;
    const parts = entry.message?.content ?? [];
    if (entry.role === 'user') {
      const text = parts.filter((p) => p.type === 'text').map((p) => p.text).join('\n');
      const query = text.match(/<user_query>([\s\S]*?)<\/user_query>/)?.[1]?.trim() ?? text.trim();
      const time = text.match(/<timestamp>(.*?)<\/timestamp>/)?.[1];
      md.push('---', '', `## User${time ? ` (${time})` : ''}`, '', query, '');
    } else {
      const body = parts.map((p) => (p.type === 'text' ? p.text.trim() : p.type === 'tool_use' ? toolSummary(p) : '')).filter(Boolean);
      if (body.length) md.push('### Assistant', '', body.join('\n\n'), '');
    }
  }
  writeFileSync(join(OUT, `${name}.md`), md.join('\n'));
  copyFileSync(file, join(OUT, `${name}.raw.jsonl`));
  console.log(`${name}: ${lines.length} entries`);
}
